import React, { FC, HTMLAttributes } from 'react';

import { Flex, Typography } from 'antd';
import cn from 'classnames';

import emptyImage from 'assets/images/emptyStates/face-with-sweat.webp';

import styles from './NoResults.module.scss';

interface INoResultsProps extends HTMLAttributes<HTMLDivElement> {
	text?: string;
	subtext?: string;
	goTo?: React.ReactNode;
}

export const NoResults: FC<INoResultsProps> = ({ className, goTo, text, subtext, ...props }) => {
	return (
		<Flex vertical gap={8} {...props} className={cn(className, styles.noResults)} align="center">
			<img src={emptyImage} width={55} height={52} alt={text} />
			{!!text && (
				<Typography.Title type="secondary" level={3} style={{ margin: 0 }}>
					{text}
				</Typography.Title>
			)}
			{!!subtext && (
				<Typography.Paragraph type="secondary" style={{ margin: 0 }}>
					{subtext}
				</Typography.Paragraph>
			)}
			{!!goTo && goTo}
		</Flex>
	);
};
